-- [[ MODULE: core\anti_tamper.lua ]]
local Core_AntiTamper = (function()
-- ====================================================================
-- CORE MODULE: ANTI-TAMPER & EXECUTOR SAFEGUARDS
-- ====================================================================
return function(ctx)
    local AntiTamper = {}

    function AntiTamper.CheckEnvironment()
        local checks = {
            hasGetgenv = type(getgenv) == "function",
            hasHookFunction = type(hookfunction) == "function" or type(replaceclosure) == "function",
            hasRequest = type(request) == "function" or type(http_request) == "function" or (syn and type(syn.request) == "function") or (fluxus and type(fluxus.request) == "function"),
            hasGetConnections = type(getconnections) == "function"
        }
        return checks
    end

    function AntiTamper.GetSafeGuiParent()
        local CoreGui = game:GetService("CoreGui")
        local Players = game:GetService("Players")
        local LocalPlayer = Players.LocalPlayer

        if gethui then
            return gethui()
        end

        local ok, parent = pcall(function()
            return CoreGui
        end)
        if ok and parent then return CoreGui end

        return LocalPlayer and LocalPlayer:FindFirstChild("PlayerGui")
    end

    return AntiTamper
end
end)()

-- [[ MODULE: core\config_manager.lua ]]
local Core_ConfigManager = (function()
-- ====================================================================
-- CORE MODULE: PERSISTENT CONFIGURATION MANAGER (JSON SAVE / LOAD)
-- ====================================================================
return function(ctx)
    local HttpService = game:GetService("HttpService")
    local Config = {}
    Config.__index = Config

    local CONFIG_FILE = "StealAnEgg_Config.json"
    local configData = {}

    local isfile = isfile or function(f) return false end
    local readfile = readfile or function(f) return "{}" end
    local writefile = writefile or function(f, c) end

    function Config:Init(customFileName)
        if customFileName then CONFIG_FILE = customFileName end
        self:Load()
        return self
    end

    function Config:Load()
        pcall(function()
            if isfile(CONFIG_FILE) then
                local content = readfile(CONFIG_FILE)
                if content and #content > 0 then
                    configData = HttpService:JSONDecode(content) or {}
                end
            end
        end)
    end

    function Config:Save()
        pcall(function()
            local content = HttpService:JSONEncode(configData)
            writefile(CONFIG_FILE, content)
        end)
    end

    function Config:Get(key, default)
        if configData[key] ~= nil then
            return configData[key]
        end
        return default
    end

    function Config:Set(key, value)
        configData[key] = value
        self:Save()
    end

    function Config:GetAll()
        return configData
    end

    return setmetatable({}, Config):Init()
end
end)()

