-- [[ MODULE: core\system_controller.lua ]]
local Core_SystemController = (function()
-- ====================================================================
-- CORE MODULE: SYSTEM CONTROLLER & CENTRAL EVENT BUS
-- ====================================================================
return function(ctx)
    local SystemController = {
        IsPaused = false,
        _registeredModules = {}
    }

    function SystemController.RegisterModule(moduleName, toggleCallback)
        SystemController._registeredModules[moduleName] = toggleCallback
    end

    function SystemController.PauseAll()
        SystemController.IsPaused = true
        for name, callback in pairs(SystemController._registeredModules) do
            pcall(callback, false)
        end
    end

    function SystemController.ResumeAll()
        SystemController.IsPaused = false
        for name, callback in pairs(SystemController._registeredModules) do
            pcall(callback, true)
        end
    end

    return SystemController
end
end)()

-- [[ MODULE: core\utilities.lua ]]
local Core_Utilities = (function()
-- ====================================================================
-- CORE MODULE: UTILITIES, ESP ENGINE & SYSTEM HELPERS
-- ====================================================================
return function(ctx)
    local Utils = {}
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer
    local Workspace = game:GetService("Workspace")
    local RepStorage = game:GetService("ReplicatedStorage")
    local Localization = ctx.Localization

    local LOG_FILE = "StealAnEgg_Errors.log"
    local appendfile = appendfile or function(f, c)
        local cur = (isfile and isfile(f) and readfile and readfile(f)) or ""
        if writefile then writefile(f, cur .. c) end
    end
    local writefile = writefile or function(f, c) end
    local readfile = readfile or function(f) return "" end
    local isfile = isfile or function(f) return false end
    local delfile = delfile or function(f) end

    -- 1. Helper dịch thuật
    function Utils.t(key)
        if Localization and Localization.t then
            return Localization.t(key)
        end
        return key
    end

    -- 2. Bảng ánh xạ Icon chuẩn của Rayfield Gen 2 (Lucide Icons)
    local LucideIconMap = {
        ["zap"] = "zap",
        ["server"] = "server",
        ["shield"] = "shield",
        ["sword"] = "sword",
        ["award"] = "award",
        ["eye"] = "eye",
        ["map"] = "map",
        ["gift"] = "gift",
        ["bell"] = "bell",
        ["crosshair"] = "crosshair",
        ["target"] = "crosshair",
        ["user"] = "user",
        ["settings"] = "settings",
        ["list"] = "list",
        ["heart"] = "heart"
    }

    function Utils.GetIcon(name)
        if type(name) == "string" and LucideIconMap[name] then
            return LucideIconMap[name]
        end
        return name or "sword"
    end

    -- 3. HỆ THỐNG GHI LOG LỖI CỤC BỘ & STACK TRACE
    function Utils.LogError(err, errorContext)
        errorContext = errorContext or "Unknown"
        local timestamp = os.date("[%Y-%m-%d %X]")
        local stackTrace = debug.traceback()
        local formattedLog = string.format("\n%s [ERROR] [%s] %s\nStack Trace:\n%s\n%s\n", 
            timestamp, errorContext, tostring(err), tostring(stackTrace), string.rep("-", 50))

        warn(formattedLog)

        pcall(function()
            appendfile(LOG_FILE, formattedLog)
        end)

        pcall(function()
            if ctx and ctx.Webhook and type(ctx.Webhook.SendWebhook) == "function" then
                ctx.Webhook.SendWebhook("❌ Script Error Detected", 
                    "**Context:** " .. errorContext .. "\n**Error:** " .. tostring(err) .. "\n```" .. tostring(stackTrace):sub(1, 1500) .. "```", 
                    16711680)
            end
        end)
    end

    function Utils.SafeCall(func, errorContext)
        errorContext = errorContext or "SafeCall"
        local success, result = xpcall(func, function(err)
            return {
                error = err,
                stack = debug.traceback()
            }
        end)

        if not success then
            Utils.LogError(result.error, errorContext)
        end
        return success, result
    end

    -- 4. Lấy dữ liệu Character an toàn
    function Utils.GetCharData()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hrp and hum and hum.Health > 0 then
            return char, hrp, hum
        end
        return nil, nil, nil
    end

    -- 5. Bắn Raycast tìm chính xác mặt đất vững chắc
    function Utils.GetGroundPosition(targetPos, offsetHeight)
        if not targetPos then return nil end
        offsetHeight = offsetHeight or 3.5
        local rayOrigin = Vector3.new(targetPos.X, targetPos.Y + 40, targetPos.Z)
        local rayDirection = Vector3.new(0, -300, 0)
        local raycastParams = RaycastParams.new()
        raycastParams.FilterType = Enum.RaycastFilterType.Exclude
        if LocalPlayer.Character then
            raycastParams.FilterDescendantsInstances = { LocalPlayer.Character }
        end
        local result = Workspace:Raycast(rayOrigin, rayDirection, raycastParams)
        if result then
            return result.Position + Vector3.new(0, offsetHeight, 0)
        end
        return targetPos + Vector3.new(0, offsetHeight, 0)
    end

    -- 6. Fire ProximityPrompt an toàn
    function Utils.FirePrompt(prompt)
        if not prompt or not prompt.Parent then return false end
        local fpp = fireproximityprompt or function(p)
            if p.InputHoldBegin then
                p:InputHoldBegin()
                task.wait((p.HoldDuration or 0) + 0.05)
                p:InputHoldEnd()
            end
        end
        local ok = pcall(function()
            fpp(prompt)
        end)
        return ok
    end

    -- 7. Tìm Base/Tổ của người chơi cục bộ
    function Utils.GetMyBase()
        local plots = Workspace:FindFirstChild("Plots") or Workspace:FindFirstChild("Bases") or Workspace:FindFirstChild("PlayerBases")
        if plots then
            for _, p in ipairs(plots:GetChildren()) do
                local sign = p:FindFirstChild("PlotSign")
                local signText = sign and sign:FindFirstChildWhichIsA("TextLabel", true)
                if signText and string.find(signText.Text:lower(), LocalPlayer.Name:lower()) then
                    return p
                end
                if string.find(p.Name:lower(), LocalPlayer.Name:lower()) then
                    return p
                end
            end
        end
        return nil
    end

    function Utils.GetMyBasePosition()
        local base = Utils.GetMyBase()
        if base then
            local center = base:FindFirstChild("CenterPoint") or base:FindFirstChild("SpawnPoint") or base:FindFirstChild("Deposit") or base:FindFirstChild("Nest") or base.PrimaryPart or base:FindFirstChildWhichIsA("BasePart")
            if center then return center.Position end
        end
        local spawns = Workspace:FindFirstChild("SpawnLocation") or Workspace:FindFirstChild("Spawns")
        if spawns and spawns:IsA("BasePart") then return spawns.Position end
        return nil
    end

    -- 8. Kiểm tra trứng đang cầm trên tay/balo
    function Utils.GetHeldEgg()
        local char = LocalPlayer.Character
        if char then
            for _, item in ipairs(char:GetChildren()) do
                if (item:IsA("Tool") or item:IsA("Model")) and string.find(item.Name:lower(), "egg") then
                    return item
                end
            end
        end
        local bp = LocalPlayer:FindFirstChild("Backpack")
        if bp then
            for _, item in ipairs(bp:GetChildren()) do
                if string.find(item.Name:lower(), "egg") then
                    return item
                end
            end
        end
        return nil
    end

    -- 9. Remote Finder & Safe Invoker
    function Utils.FindRemote(nameList, remoteType)
        remoteType = remoteType or "RemoteEvent"
        for _, obj in ipairs(RepStorage:GetDescendants()) do
            if obj:IsA(remoteType) then
                for _, name in ipairs(nameList) do
                    if string.lower(obj.Name) == string.lower(name) then
                        return obj
                    end
                end
            end
        end
        return nil
    end

    function Utils.FireServerSafe(remoteNames, ...)
        local remote = Utils.FindRemote(remoteNames, "RemoteEvent")
        if remote then
            local args = {...}
            return pcall(function()
                remote:FireServer(unpack(args))
            end)
        end
        return false
    end

    function Utils.InvokeServerSafe(remoteNames, ...)
        local remote = Utils.FindRemote(remoteNames, "RemoteFunction")
        if remote then
            local args = {...}
            local ok, res = pcall(function()
                return remote:InvokeServer(unpack(args))
            end)
            if ok then return res end
        end
        return nil
    end

    -- 10. ESP Manager Registry (Clean Teardown)
    local ActiveESP = {}

    function Utils.AddESP(instance, name, color, tag)
        if not instance then return end
        tag = tag or "Default"
        ActiveESP[tag] = ActiveESP[tag] or {}

        pcall(function()
            local adornee = instance:IsA("BasePart") and instance or (instance:IsA("Model") and (instance.PrimaryPart or instance:FindFirstChildWhichIsA("BasePart")))
            if not adornee then return end

            -- Highlight
            local highlight = Instance.new("Highlight")
            highlight.Name = "StealEgg_ESP_Highlight"
            highlight.FillColor = color or Color3.fromRGB(255, 200, 0)
            highlight.FillTransparency = 0.5
            highlight.OutlineColor = Color3.fromRGB(255, 255, 255)
            highlight.OutlineTransparency = 0.1
            highlight.Adornee = instance
            highlight.Parent = instance

            -- BillboardGui
            local bbg = Instance.new("BillboardGui")
            bbg.Name = "StealEgg_ESP_BBG"
            bbg.Adornee = adornee
            bbg.Size = UDim2.new(0, 150, 0, 40)
            bbg.StudsOffset = Vector3.new(0, 3, 0)
            bbg.AlwaysOnTop = true

            local label = Instance.new("TextLabel")
            label.Size = UDim2.new(1, 0, 1, 0)
            label.BackgroundTransparency = 1
            label.Text = name or instance.Name
            label.TextColor3 = color or Color3.fromRGB(255, 255, 255)
            label.TextStrokeTransparency = 0.2
            label.TextScaled = false
            label.TextSize = 13
            label.Font = Enum.Font.GothamBold
            label.Parent = bbg
            bbg.Parent = adornee

            table.insert(ActiveESP[tag], { Highlight = highlight, Billboard = bbg, Instance = instance })
        end)
    end

    function Utils.ClearESP(tag)
        if tag and ActiveESP[tag] then
            for _, item in ipairs(ActiveESP[tag]) do
                pcall(function()
                    if item.Highlight then item.Highlight:Destroy() end
                    if item.Billboard then item.Billboard:Destroy() end
                end)
            end
            ActiveESP[tag] = {}
        elseif not tag then
            for tName, list in pairs(ActiveESP) do
                for _, item in ipairs(list) do
                    pcall(function()
                        if item.Highlight then item.Highlight:Destroy() end
                        if item.Billboard then item.Billboard:Destroy() end
                    end)
                end
            end
            ActiveESP = {}
        end
    end

    -- 11. Format Number
    function Utils.FormatNumber(num)
        if not num or type(num) ~= "number" then return tostring(num or 0) end
        local suffixes = {"", "K", "M", "B", "T", "Qa", "Qi"}
        local i = 1
        while num >= 1000 and i < #suffixes do
            num = num / 1000
            i = i + 1
        end
        return string.format(i == 1 and "%d" or "%.2f%s", num, suffixes[i])
    end

    return Utils
end
end)()

-- [[ MODULE: core\webhook.lua ]]
local Core_Webhook = (function()
-- ====================================================================
-- CORE MODULE: DISCORD WEBHOOK INTEGRATION
-- ====================================================================
return function(ctx)
    local Webhook = {}
    local HttpService = game:GetService("HttpService")
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer
    local GuiService = game:GetService("GuiService")
    local Config = ctx.Config

    local requestFunc = request or http_request or (syn and syn.request) or (fluxus and fluxus.request) or (identifyexecutor and request)

    function Webhook.SendWebhook(title, description, color, fields)
        local enabled = Config and Config:Get("Webhook.Enabled", false) or false
        local url = Config and Config:Get("Webhook.Url", "") or ""
        if not enabled or not url or url == "" or not requestFunc then return end

        local embedFields = {
            { name = "👤 Player", value = LocalPlayer.Name .. " (@" .. LocalPlayer.DisplayName .. ")", inline = true },
            { name = "🕒 Time", value = os.date("%X"), inline = true }
        }

        if fields and type(fields) == "table" then
            for _, f in ipairs(fields) do
                table.insert(embedFields, f)
            end
        end

        local data = {
            username = "Steal An Egg Bot",
            avatar_url = "https://i.imgur.com/8m5sQvW.png",
            embeds = {
                {
                    title = title or "🥚 Steal An Egg Notification",
                    description = description or "",
                    color = color or 65280,
                    fields = embedFields,
                    footer = { text = "Steal An Egg Hub • Sơn Studio" },
                    timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ")
                }
            }
        }

        pcall(function()
            requestFunc({
                Url = url,
                Method = "POST",
                Headers = { ["Content-Type"] = "application/json" },
                Body = HttpService:JSONEncode(data)
            })
        end)
    end

    function Webhook.SendRareEggAlert(eggName, eggRarity, eggValue)
        local sendRare = Config and Config:Get("Webhook.SendOnRareEgg", true) or true
        if not sendRare then return end

        Webhook.SendWebhook("🌟 RARE EGG SECURED!", 
            "A rare egg has been collected or spotted on the server!", 
            16766720, -- Gold
            {
                { name = "🥚 Egg Type", value = tostring(eggName or "Unknown Egg"), inline = true },
                { name = "✨ Rarity", value = tostring(eggRarity or "Rare+"), inline = true },
                { name = "💰 Value", value = tostring(eggValue or "High"), inline = true }
            }
        )
    end

    function Webhook.SendDisconnectAlert(reason)
        local sendDc = Config and Config:Get("Webhook.SendOnDisconnect", true) or true
        if not sendDc then return end

        Webhook.SendWebhook("⚠️ PLAYER DISCONNECTED / KICKED", 
            "The client has lost connection or was kicked from the server.", 
            16711680, -- Red
            {
                { name = "🚨 Reason", value = tostring(reason or "Lost connection to server"), inline = false }
            }
        )
    end

    -- Hook error disconnect event
    pcall(function()
        GuiService.ErrorMessageChanged:Connect(function()
            local msg = GuiService:GetErrorMessage()
            if msg and msg ~= "" then
                Webhook.SendDisconnectAlert(msg)
            end
        end)
    end)

    return Webhook
end
end)()

