            if eggFolder then
                for _, model in ipairs(eggFolder:GetChildren()) do
                    local isParasite = model:FindFirstChild("MonsterParasiteVisual", true) ~= nil or model:GetAttribute("MonsterParasite") ~= nil or model:GetAttribute("Parasite") ~= nil
                    if isParasite then
                        local part = model:FindFirstChild("Hitbox") or model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
                        if part then
                            local dist = (hrp.Position - part.Position).Magnitude
                            if dist < closestDist then
                                closestDist = dist
                                targetEgg = { model = model, part = part, uid = model.Name }
                            end
                        end
                    end
                end
            end

            if not targetEgg then
                Notify("Monster Event", "No parasite eggs found on map!", 3)
                return
            end

            -- 1. Teleport & Carry Parasite Egg
            hrp.CFrame = CFrame.new(targetEgg.part.Position + Vector3.new(0, 2.5, 0))
            task.wait(0.2)
            local askCarry = RepStorage:FindFirstChild("Packages") and RepStorage.Packages:FindFirstChild("Networking") and RepStorage.Packages.Networking:FindFirstChild("RF/EggWorld/AskFieldEggCarry")
            if askCarry then
                pcall(function() askCarry:InvokeServer({ Uid = targetEgg.uid }) end)
            end
            task.wait(0.35)

            -- 2. Teleport to Monster & Feed
            local monstersFolder = Workspace:FindFirstChild("MonsterParasiteMonsters")
            local monster = monstersFolder and monstersFolder:FindFirstChildWhichIsA("Model")
            local root = monster and (monster:FindFirstChild("RootPart") or monster.PrimaryPart)

            if root then
                hrp.CFrame = CFrame.new(root.Position + Vector3.new(0, 0, 4), root.Position)
                task.wait(0.25)
                local askFeed = RepStorage.Packages.Networking:FindFirstChild("RF/MonsterParasite/AskFeed")
                if askFeed then
                    pcall(function() askFeed:InvokeServer() end)
                end
                Notify("Monster Event", "Fed parasite egg to The Hungry Monster!", 3)
            end
        end
    })

    -- ==========================================
    -- 5. BACKGROUND ENGINES & LOOPS
    -- ==========================================

    -- Helper: Match Egg Filters
    local function MatchesEggFilter(eggInstance)
        if not eggInstance then return false end
        local nameLower = eggInstance.Name:lower()

        if stealBigEggs then
            if string.find(nameLower, "big") or string.find(nameLower, "giant") or string.find(nameLower, "huge") or string.find(nameLower, "colossal") then
                return true
            end
        end

        if autoStealAll then return true end

        if autoStealSelected and type(selectedEggsList) == "table" then
            for _, selected in ipairs(selectedEggsList) do
                local sLower = tostring(selected):lower()
                if string.find(nameLower, sLower:gsub(" egg", "")) or string.find(nameLower, sLower) then
                    return true
                end
            end
        end

        return false
    end

    -- Helper: Perform Safe Server Hop
    local function PerformServerHop()
        local placeId = game.PlaceId
        local serversUrl = "https://games.roblox.com/v1/games/" .. placeId .. "/servers/Public?sortOrder=Asc&limit=100"
        pcall(function()
            local req = request or http_request or (syn and syn.request) or (fluxus and fluxus.request)
            if req then
                local res = req({ Url = serversUrl, Method = "GET" })
                if res and res.Body then
                    local data = HttpService:JSONDecode(res.Body)
                    if data and data.data then
                        for _, s in ipairs(data.data) do
                            if s.playing < s.maxPlayers and s.id ~= game.JobId then
                                TeleportService:TeleportToPlaceInstance(placeId, s.id, LocalPlayer)
                                return
                            end
                        end
                    end
                end
            end
            TeleportService:Teleport(placeId, LocalPlayer)
        end)
    end

    -- Loop 1: Auto Steal, Return, Drop, Server Hop Engine
    task.spawn(function()
        local consecutiveEmptyRuns = 0

        while task.wait(0.35) do
            if (autoStealSelected or autoStealAll or stealBigEggs or autoDropHeldEgg) and not (SystemController and SystemController.IsPaused) then
                pcall(function()
                    local char, hrp, hum = Utils.GetCharData()
                    if not char or not hrp or not hum then return end

                    -- Check if holding egg
                    local heldEgg = Utils.GetHeldEgg()

                    -- Drop held egg if enabled
                    if autoDropHeldEgg and heldEgg then
                        local dropGui = LocalPlayer.PlayerGui:FindFirstChild("DropHeldEgg")
                        local dropBtn = dropGui and dropGui:FindFirstChild("Button", true)
                        if dropBtn then
                            if firesignal then firesignal(dropBtn.MouseButton1Click); firesignal(dropBtn.Activated) end
                            if getconnections then
                                for _, c in ipairs(getconnections(dropBtn.MouseButton1Click)) do c:Fire() end
                                for _, c in ipairs(getconnections(dropBtn.Activated)) do c:Fire() end
                            end
                        end
                        Utils.FireServerSafe({"DropEgg", "DropHeldEgg", "DropItem", "Drop"}, heldEgg)
                        task.wait(0.2)
                        return
                    end

                    -- Return to Base and Place Egg if holding egg and return enabled
                    if autoReturnToBase and heldEgg then
                        local basePos = Utils.GetMyBasePosition()
                        if basePos then
                            hrp.CFrame = CFrame.new(basePos + Vector3.new(0, 3, 0))
                            task.wait(0.3)

                            -- Đặt trứng xuống chuồng bằng Remote chính thức RF/EggWorld/AskPlaceEgg
                            local eggUid = heldEgg:GetAttribute("UID")
                            local askPlaceEgg = RepStorage:FindFirstChild("Packages") and RepStorage.Packages:FindFirstChild("Networking") and RepStorage.Packages.Networking:FindFirstChild("RF/EggWorld/AskPlaceEgg")
                            if askPlaceEgg and eggUid then
                                pcall(function()
                                    askPlaceEgg:InvokeServer({
                                        LocalCFrame = CFrame.new(0, 0, 0),
                                        Uid = eggUid
                                    })
                                end)
                            end

                            task.wait(0.3)
                        end
                        return
                    end

                    -- Scan Workspace for Eggs (SmartPromptPart, AreaEggSlotsClient, Eggs folder)
                    local bestEgg = nil
                    local bestDist = 999999

                    -- 1. Ưu tiên quét SmartPromptPart (Native Prompt của Steal An Egg)
                    for _, v in ipairs(Workspace:GetChildren()) do
                        if v.Name == "SmartPromptPart" then
