                                                LocalCFrame = CFrame.new(0, 0, 0),
                                                Uid = eggUid
                                            })
                                        end)
                                    end
                                end
                                task.wait(0.2)
                            end
                        end
                    else
                        consecutiveEmptyRuns = consecutiveEmptyRuns + 1
                        if autoServerHop and consecutiveEmptyRuns >= 15 then
                            consecutiveEmptyRuns = 0
                            Notify("Server Hop", "No target eggs found. Hopping to a new server...", 3)
