                pcall(function()
                    local pets = Workspace:FindFirstChild("New Pets") or Workspace:FindFirstChild("Pets") or Workspace:FindFirstChild("WorldPets")
                    if pets then
                        for _, p in ipairs(pets:GetChildren()) do
                            Utils.AddESP(p, "🐾 " .. p.Name, Color3.fromRGB(170, 85, 255), "Pet")
                        end
                    end
                end)
            end

            if machineEsp then
                Utils.ClearESP("Machine")
                pcall(function()
                    local objects = Workspace:FindFirstChild("__OBJECTS")
                    local machines = objects and objects:FindFirstChild("Machines")
                    if machines then
                        for _, m in ipairs(machines:GetChildren()) do
                            Utils.AddESP(m, "⚙️ " .. m.Name, Color3.fromRGB(85, 255, 127), "Machine")
                        end
                    end
                    local groupReward = objects and objects:FindFirstChild("GroupReward")
                    if groupReward then
                        Utils.AddESP(groupReward, "🎁 Group Chest", Color3.fromRGB(255, 215, 0), "Machine")
                    end
                end)
            end

            if plotEsp then
                Utils.ClearESP("Plot")
                pcall(function()
                    local plots = Workspace:FindFirstChild("Plots")
                    if plots then
                        for _, plot in ipairs(plots:GetChildren()) do
                            local center = plot:FindFirstChild("CenterPoint") or plot:FindFirstChild("SpawnPoint")
                            local sign = plot:FindFirstChild("PlotSign")
                            local signText = sign and sign:FindFirstChildWhichIsA("TextLabel", true)
                            local ownerName = signText and signText.Text or ("Plot " .. plot.Name)
                            if center then
                                Utils.AddESP(center, "🏰 Base: " .. ownerName, Color3.fromRGB(255, 170, 0), "Plot")
                            end
                        end
                    end
                end)
            end
        end
    end)

    -- ==========================================
    -- 4. MOVEMENT & FLIGHT RUNTIME
    -- ==========================================
    RunService.RenderStepped:Connect(function()
        pcall(function()
            local char, hrp, hum = Utils.GetCharData()
            if not char or not hrp or not hum then return end

            if walkSpeedOverride then
                hum.WalkSpeed = walkSpeedValue
            end

            if jumpPowerOverride then
                hum.UseJumpPower = true
                hum.JumpPower = jumpPowerValue
            end

            if noClip then
                for _, part in ipairs(char:GetDescendants()) do
                    if part:IsA("BasePart") then
                        part.CanCollide = false
                    end
                end
            end

            if fly then
                local camera = Workspace.CurrentCamera
                local moveDir = Vector3.new(0, 0, 0)
                if UserInputService:IsKeyDown(Enum.KeyCode.W) then moveDir = moveDir + camera.CFrame.LookVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.S) then moveDir = moveDir - camera.CFrame.LookVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.D) then moveDir = moveDir + camera.CFrame.RightVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.A) then moveDir = moveDir - camera.CFrame.RightVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.Space) then moveDir = moveDir + Vector3.new(0, 1, 0) end
                if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then moveDir = moveDir - Vector3.new(0, 1, 0) end

                if moveDir.Magnitude > 0 then
                    hrp.Velocity = moveDir.Unit * (flySpeed * 50)
                else
                    hrp.Velocity = Vector3.new(0, 0, 0)
                end
            end
        end)
    end)

    -- Infinite Jump Handler
    UserInputService.JumpRequest:Connect(function()
        if infiniteJump then
            local _, _, hum = Utils.GetCharData()
            if hum then
                hum:ChangeState(Enum.HumanoidStateType.Jumping)
            end
        end
    end)
end
end)()

