    -- ==========================================
    local enablePrioritySystem = Config and Config:Get("Priority.Enabled", true) or true
    local priorityFocus = Config and Config:Get("Priority.Focus", "Secret > Godly > Mythic") or "Secret > Godly > Mythic"
    local prioritizeWeakBases = Config and Config:Get("Priority.WeakBases", true) or true
    local prioritizeGiantEggs = Config and Config:Get("Priority.GiantEggs", true) or true

    PriorityTab:CreateSection(tFunc("sec_priority"))

    PriorityTab:CreateToggle({
