            enablePrioritySystem = v
            if Config then Config:Set("Priority.Enabled", v) end
            if v then Notify("Priority System", "Priority targeting engine activated!", 2) end
        end
    })

    PriorityTab:CreateDropdown({
        Name = tFunc("dropdown_priority_target"),
        Options = {
            "Secret > Godly > Mythic",
            "Giant / Big Eggs First",
            "Highest Value Eggs",
            "Closest Distance",
            "Unprotected Bases First"
        },
        CurrentOption = {priorityFocus},
        MultipleOptions = false,
        Flag = "DropdownPriorityFocus",
        Callback = function(opt)
            priorityFocus = type(opt) == "table" and opt[1] or opt
            if Config then Config:Set("Priority.Focus", priorityFocus) end
        end
    })

    PriorityTab:CreateToggle({
        Name = "Prioritize Giant / Colossal Eggs",
        CurrentValue = prioritizeGiantEggs,
        Flag = "TogglePrioritizeGiantEggs",
        Callback = function(v)
            prioritizeGiantEggs = v
            if Config then Config:Set("Priority.GiantEggs", v) end
        end
    })

    PriorityTab:CreateToggle({
        Name = "Target Unprotected / AFK Player Bases",
        CurrentValue = prioritizeWeakBases,
        Flag = "TogglePrioritizeWeakBases",
        Callback = function(v)
            prioritizeWeakBases = v
            if Config then Config:Set("Priority.WeakBases", v) end
        end
    })

    PriorityTab:CreateButton({
        Name = "⚡ Fast Priority Scan & Snipe Now",
        Callback = function()
            local char, hrp = Utils.GetCharData()
            if not hrp then return end

            local eggsFolder = Workspace:FindFirstChild("Eggs") or Workspace:FindFirstChild("SpawnedEggs") or Workspace
            local targetEgg = nil
            local highestRank = -1

            local rarityRanks = {
                ["secret"] = 100,
                ["godly"] = 90,
                ["mythic"] = 80,
                ["giant"] = 70,
                ["huge"] = 65,
                ["legendary"] = 50,
                ["epic"] = 30,
                ["rare"] = 20,
                ["common"] = 10
            }

            for _, item in ipairs(eggsFolder:GetDescendants()) do
                if (item:IsA("Model") or item:IsA("BasePart")) and string.find(item.Name:lower(), "egg") and not string.find(item.Name:lower(), "nest") then
                    local part = item:IsA("BasePart") and item or item.PrimaryPart or item:FindFirstChildWhichIsA("BasePart")
                    if part then
                        local rank = 5
                        local nameLower = item.Name:lower()
                        for rKey, rVal in pairs(rarityRanks) do
                            if string.find(nameLower, rKey) then
                                if rVal > rank then rank = rVal end
                            end
                        end

                        if rank > highestRank then
                            highestRank = rank
                            targetEgg = { Instance = item, Part = part }
                        end
                    end
                end
            end

            if targetEgg and targetEgg.Part then
                hrp.CFrame = CFrame.new(targetEgg.Part.Position + Vector3.new(0, 3, 0))
                Notify("Priority Snipe", "Teleported to priority target: " .. targetEgg.Instance.Name, 3)
            else
                Notify("Priority Snipe", "No active high-priority eggs found.", 3)
            end
        end
    })
end
end)()

