local Feature_ServerManager = (function()
-- ====================================================================
-- FEATURE MODULE: SERVER UTILITIES & FPS BOOST
-- ====================================================================
return function(ctx)
    local Window = ctx.Window
    local Utils = ctx.Utils
    local Config = ctx.Config

    local TeleportService = game:GetService("TeleportService")
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer
    local HttpService = game:GetService("HttpService")

    local tFunc = function(k)
        if Utils and Utils.t then return Utils.t(k) end
        return k
    end

    local function Notify(title, msg, dur)
        if Utils and Utils.Notify then
            Utils.Notify(title, msg, dur)
        end
    end

    local ServerTab = Window:CreateTab(tFunc("tab_server"), Utils.GetIcon("server"))

    ServerTab:CreateSection(" " .. tFunc("sec_server_controls") .. " ")

    -- 1. Vào Server Ít Người Nhất (Lowest Player Server Hop)
    ServerTab:CreateButton({
        Name = tFunc("btn_server_hop_lowest"),
        Callback = function()
            Notify(tFunc("system_title"), "Scanning for smallest servers...", 2)
            task.spawn(function()
                local success, err = pcall(function()
                    local url = "https://games.roblox.com/v1/games/" .. tostring(game.PlaceId) .. "/servers/Public?sortOrder=Asc&limit=100"
                    local response = game:HttpGet(url)
                    local data = HttpService:JSONDecode(response)

                    if data and data.data and #data.data > 0 then
                        local bestServer = nil
                        local minPlayers = 999999

                        for _, s in ipairs(data.data) do
                            if s.id ~= game.JobId and s.playing and s.playing < s.maxPlayers and s.playing > 0 then
                                if s.playing < minPlayers then
                                    minPlayers = s.playing
                                    bestServer = s
                                end
                            end
                        end

                        if bestServer then
                            Notify(tFunc("success_title"), "Found server with " .. tostring(bestServer.playing) .. " players! Teleporting...", 3)
                            TeleportService:TeleportToPlaceInstance(game.PlaceId, bestServer.id, LocalPlayer)
                        else
                            Notify(tFunc("warning_title"), "No suitable small server found!", 3)
                        end
                    else
                        Notify(tFunc("warning_title"), "Failed to fetch server list!", 3)
                    end
                end)

                if not success then
                    Notify(tFunc("error_title"), "Server Hop Error: " .. tostring(err), 3)
                end
            end)
        end
    })

    -- 2. Chuyển Server Ngẫu Nhiên (Random Server Hop)
    ServerTab:CreateButton({
        Name = tFunc("btn_server_hop"),
        Callback = function()
            Notify(tFunc("system_title"), "Hopping to random server...", 2)
            task.spawn(function()
                pcall(function()
                    local url = "https://games.roblox.com/v1/games/" .. tostring(game.PlaceId) .. "/servers/Public?sortOrder=Asc&limit=100"
                    local response = game:HttpGet(url)
                    local data = HttpService:JSONDecode(response)

                    if data and data.data then
                        local validServers = {}
                        for _, s in ipairs(data.data) do
                            if s.playing < s.maxPlayers and s.id ~= game.JobId then
                                table.insert(validServers, s)
                            end
                        end

                        if #validServers > 0 then
                            local chosen = validServers[math.random(1, #validServers)]
                            TeleportService:TeleportToPlaceInstance(game.PlaceId, chosen.id, LocalPlayer)
                        end
                    end
                end)
            end)
        end
    })

    -- 3. Vào Lại Server Hiện Tại (Rejoin)
    ServerTab:CreateButton({
        Name = tFunc("btn_rejoin"),
        Callback = function()
            Notify(tFunc("system_title"), "Rejoining current server...", 2)
            TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
        end
    })

    -- 4. Sao Chép Server Job ID
    ServerTab:CreateButton({
        Name = tFunc("btn_copy_job_id"),
        Callback = function()
            if setclipboard then
                setclipboard(tostring(game.JobId))
                Notify(tFunc("success_title"), "Copied Server Job ID to clipboard!", 2)
            else
                Notify(tFunc("warning_title"), "Clipboard API not supported!", 2)
            end
        end
    })

    -- 5. Chống Bị Đuổi Khi AFK (Anti-AFK)
    ServerTab:CreateToggle({
        Name = tFunc("toggle_anti_afk"),
        CurrentValue = true,
        Flag = "ServerAntiAfk",
        Callback = function(Value)
            if Value then
                LocalPlayer.Idled:Connect(function()
                    local vu = game:GetService("VirtualUser")
                    if vu then
                        vu:CaptureController()
                        vu:ClickButton2(Vector2.new())
                    end
                end)
            end
        end
    })

    ServerTab:CreateSection(" " .. tFunc("sec_performance") .. " ")

    -- 6. Tối Ưu Đồ Họa & Tăng FPS (FPS Booster)
    ServerTab:CreateToggle({
        Name = tFunc("toggle_fps_boost"),
        CurrentValue = false,
        Flag = "ServerFpsBoost",
        Callback = function(Value)
            if Value then
                pcall(function()
                    for _, v in ipairs(game:GetDescendants()) do
                        if v:IsA("BasePart") then
                            v.Material = Enum.Material.SmoothPlastic
                        elseif v:IsA("Decal") or v:IsA("Texture") then
                            v.Transparency = 1
                        end
                    end
                end)
                Notify("FPS Boost", "Graphics optimized for max performance!", 2)
            end
        end
    })
end
end)()

